int N, M, Q;
long long K;
Effect spells[100005];
Effect meals[100005];

int main() {
    if (scanf("%d %d %lld", &N, &M, &K) != 3) return 0;

    for (int i = 0; i < N; i++) scanf("%lld", &spells[i].a);
    for (int i = 0; i < N; i++) scanf("%lld", &spells[i].b);
    for (int i = 0; i < M; i++) scanf("%lld", &meals[i].a);
    for (int i = 0; i < M; i++) scanf("%lld", &meals[i].b);

    // 1. Process Meals
    qsort(meals, M, sizeof(Effect), cmp_meals);

    long long A_meal = 1, B_meal = 0;
    for (int i = 0; i < M; i++) {
        A_meal = (A_meal * (meals[i].a % MOD)) % MOD;
        B_meal = ((meals[i].a % MOD) * B_meal + (meals[i].b % MOD)) % MOD;
    }

    // 2. Process Spells
    long long max_add_b = 0;
    int has_mult = 0;

    for (int i = 0; i < N; i++) {
        if (spells[i].a == 1) {
            if (spells[i].b > max_add_b) {
                max_add_b = spells[i].b;
            }
        } else {
            has_mult = 1;
        }
    }

    Effect best_spell = {1, 0};

    if (has_mult) {
        // Find the best multiplicative spell
        // A spell with larger 'a' dominates for large K.
        // For identical 'a', larger 'b' dominates.
        // What if K is small? We compare f^(K)(x).
        // Since we want to select the best spell to repeat K times:
        int best_idx = -1;
        for (int i = 0; i < N; i++) {
            if (spells[i].a > 1) {
                if (best_idx == -1) {
                    best_idx = i;
                } else {
                    if (spells[i].a > spells[best_idx].a) {
                        best_idx = i;
                    } else if (spells[i].a == spells[best_idx].a) {
                        if (spells[i].b > spells[best_idx].b) {
                            best_idx = i;
                        }
                    }
                }
            }
        }
        best_spell = spells[best_idx];
    }

    // Precompute constants for best multiplicative spell
    long long a_pow = 1, geom_sum = 0;
    if (has_mult) {
        a_pow = power(best_spell.a, K);
        // geom_sum = (a^K - 1) / (a - 1) % MOD
        long long num = (a_pow - 1 + MOD) % MOD;
        long long den = modInverse((best_spell.a - 1) % MOD);
        geom_sum = (num * den) % MOD;
    }

    scanf("%d", &Q);
    while (Q--) {
        long long x;
        scanf("%lld", &x);

        long long best_x_after_spells = 0;

        if (!has_mult) {
            // Only additive spells exist
            long long total_add = ((K % MOD) * (max_add_b % MOD)) % MOD;
            best_x_after_spells = (x % MOD + total_add) % MOD;
        } else {
            // Check pure additive (if max_add_b > 0) vs pure multiplicative
            // Note: If K is very small, additive might beat multiplicative,
            // but for any large K, multiplicative easily dominates.
            int use_add = 0;
            if (max_add_b > 0 && K <= 60) {
                __int128 mult_val = x;
                for (int step = 0; step < K; step++) {
                    mult_val = mult_val * best_spell.a + best_spell.b;
                    if (mult_val > ((__int128)x + (__int128)K * max_add_b)) {
                        break;
                    }
                }
                __int128 add_val = (__int128)x + (__int128)K * max_add_b;
                if (add_val > mult_val) {
                    use_add = 1;
                }
            }

            if (use_add) {
                long long total_add = ((K % MOD) * (max_add_b % MOD)) % MOD;
                best_x_after_spells = (x % MOD + total_add) % MOD;
            } else {
                long long term1 = (a_pow * (x % MOD)) % MOD;
                long long term2 = ((best_spell.b % MOD) * geom_sum) % MOD;
                best_x_after_spells = (term1 + term2) % MOD;
            }
        }

        // Apply precomputed meals
        long long ans = (A_meal * best_x_after_spells + B_meal) % MOD;
        printf("%lld\n", ans);
    }

    return 0;
}
